143	    /**
144	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
145	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
146	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
147	     * (so the field is absent from the response) or the registration date is unknown.
148	     */
149	    public String getAgeBand() {
150	        if (this.birthDate == null || this.registrationDate == null) {
151	            return null;
152	        }
153	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
154	        if (age < 18) {
155	            return "MINOR";
156	        }
157	        if (age < 65) {
158	            return "ADULT";
159	        }
160	        return "SENIOR";
161	    }
