223	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
224	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
225	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
226	     */
227	    public Integer getPossibleDuplicateOf() {
228	        return this.possibleDuplicateOf;
229	    }
