235	    /**
236	     * The owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1; add 1 when an
237	     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
238	     * tenure and is never produced here.
239	     */
240	    public int getMembershipLevel() {
241	        int level = 1;
242	        boolean hasEmail = this.email != null && !this.email.isBlank();
243	        if (hasEmail) {
244	            level++;
245	        }
246	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
247	        if (unique) {
248	            level++;
249	        }
250	        return Math.min(level, 3);
251	    }
