253	    /**
254	     * Fixed city-to-region table mapping each known city to its canonical region string.
255	     */
256	    private static final Map<String, String> CITY_REGION = Map.of(
257	        "Sydney", "NSW",
258	        "Melbourne", "VIC",
259	        "Brisbane", "QLD");
260	
261	    /**
262	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
263	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
264	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
265	     */
266	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
267	        "NSW", new int[] {2000, 2099},
268	        "VIC", new int[] {3000, 3099},
269	        "QLD", new int[] {4000, 4099});
270	
271	    /**
272	     * The canonical region for {@code city} derived from the fixed city-to-region table
273	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
274	     * city is not in the table. The single source of truth for the create-time postcode range check in
275	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
276	     */
277	    public static String regionOf(String city) {
278	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
279	    }
280	
281	    /**
282	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
283	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
284	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
285	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
286	     * postcode range check.
287	     */
288	    public static int[] postcodeRangeOf(String region) {
289	        return REGION_POSTCODES.get(region);
290	    }
291	
292	    /**
293	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
294	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
295	     * range.
296	     */
297	    public static String regionOfPostcode(String postcode) {
298	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
299	            return null;
300	        }
301	        int value = Integer.parseInt(postcode);
302	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
303	            int[] range = entry.getValue();
304	            if (value >= range[0] && value <= range[1]) {
305	                return entry.getKey();
306	            }
307	        }
308	        return null;
309	    }
310	
311	    /**
312	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
313	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
314	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
315	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
316	     * customer code is assigned.
317	     */
318	    public String getLocality() {
319	        if (this.customerCode == null) {
320	            return "UNKNOWN";
321	        }
322	        int dash = this.customerCode.indexOf('-');
323	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
324	    }
325	
326	    /**
327	     * The single Luhn check digit (0-9) computed over the digits contained in the
328	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
329	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
330	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
331	     */
332	    public int getCheckDigit() {
333	        String code = this.customerCode;
334	        if (code == null) {
335	            return 0;
336	        }
337	        int sum = 0;
338	        boolean dbl = true;
339	        for (int i = code.length() - 1; i >= 0; i--) {
340	            char c = code.charAt(i);
341	            if (c < '0' || c > '9') {
342	                continue;
343	            }
344	            int d = c - '0';
345	            if (dbl) {
346	                d *= 2;
347	                if (d > 9) {
348	                    d -= 9;
349	                }
350	            }
351	            sum += d;
352	            dbl = !dbl;
353	        }
354	        return (10 - (sum % 10)) % 10;
355	    }
356	
357	    /**
358	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
359	     * {@code "PHONE"}.
360	     */
361	    public String getContactPreference() {
362	        boolean hasEmail = this.email != null && !this.email.isBlank();
363	        return hasEmail ? "EMAIL" : "PHONE";
364	    }
365	
366	    /**
367	     * The single canonical format of an owner's derived identity key:
368	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
369	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
370	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
371	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
372	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
373	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
374	     * {@code CheckHouseholdUnique}).
375	     */
376	    public static String identityKey(String telephone, String email, String householdId) {
377	        String tel = (telephone == null) ? "" : telephone;
378	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
379	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
380	        return tel + "|" + mail + "|" + household;
381	    }
382	
383	    /**
384	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
385	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
386	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
387	     */
388	    public String getIdentityKey() {
389	        return identityKey(this.telephone, this.email, this.householdId);
390	    }
391	
392	    protected Set<Pet> getPetsInternal() {
393	        if (this.pets == null) {
394	            this.pets = new HashSet<>();
395	        }
396	        return this.pets;
397	    }
