399	    protected void setPetsInternal(Set<Pet> pets) {
400	        this.pets = pets;
401	    }
402	
403	    public List<Pet> getPets() {
404	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
405	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
406	        return Collections.unmodifiableList(sortedPets);
407	    }
408	
409	    public void setPets(List<Pet> pets) {
410	        this.pets = new HashSet<>(pets);
411	    }
412	
413	    public void addPet(Pet pet) {
414	        getPetsInternal().add(pet);
415	        pet.setOwner(this);
416	    }
417	
418	    /**
419	     * Return the Pet with the given name, or null if none found for this Owner.
420	     *
421	     * @param name to test
422	     * @return true if pet name is already in use
423	     */
424	    public Pet getPet(String name) {
425	        return getPet(name, false);
426	    }
427	
428	    /**
429	     * Return the Pet with the given name, or null if none found for this Owner.
430	     *
431	     * @param name to test
432	     * @return true if pet name is already in use
433	     */
434	    public Pet getPet(String name, boolean ignoreNew) {
435	        name = name.toLowerCase();
436	        for (Pet pet : getPetsInternal()) {
437	            if (!ignoreNew || !pet.isNew()) {
438	                String compName = pet.getName();
439	                compName = compName.toLowerCase();
440	                if (compName.equals(name)) {
441	                    return pet;
442	                }
443	            }
444	        }
445	        return null;
446	    }
447	
448	    public Pet getPet(Integer petId) {
449	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
450	    }
451	
452	    @Override
453	    public String toString() {
454	        return new ToStringCreator(this)
455	
456	            .append("id", this.getId())
457	            .append("new", this.isNew())
458	            .append("lastName", this.getLastName())
459	            .append("firstName", this.getFirstName())
460	            .append("address", this.address)
461	            .append("city", this.city)
462	            .append("telephone", this.telephone)
463	            .toString();
464	    }
465	}
