1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * Single source of truth for what a "normalized" owner telephone is: the E.164 form.
9	 * {@link ValidateNewOwner} enforces the rule and stores the E.164 value through here, so the stored and
10	 * returned telephone (and the owner's derived identity key, which includes it) share one canonical form.
11	 *
12	 * <p>Normalization strips spaces, dashes and brackets, then forms the canonical E.164 string:
13	 * <ul>
14	 *   <li>a leading {@code '+'} and country code are kept as-is;</li>
15	 *   <li>otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
16	 *       the national digits.</li>
17	 * </ul>
18	 * The result must be a {@code '+'} followed by 8 to 15 digits. On top of that general rule, the
19	 * national-number length (the digits after the country code) must match the country code when it is one
20	 * we recognize: {@code +61} requires 9 national digits and {@code +1} requires 10 (see
21	 * {@link #NATIONAL_LENGTHS}). Anything else — non-digit leftovers, a total digit count outside 8 to 15,
22	 * or a national-number length that is wrong for a recognized country code — is not valid E.164 and
23	 * yields {@code null}. A country code that is not in the table is accepted on the general rule alone.
24	 */
25	final class OwnerTelephone {
26	
27	    /** A valid E.164 value: '+' then 8 to 15 digits. */
28	    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");
29	
30	    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
31	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
32	
33	    /**
34	     * Country code (without the '+') to its required national-number length. Iterated longest-code-first
35	     * (hence {@link LinkedHashMap}) so a longer code is matched before a shorter one that is a prefix of
36	     * the number. Country codes absent here are not length-checked.
37	     */
38	    private static final Map<String, Integer> NATIONAL_LENGTHS;
39	    static {
40	        Map<String, Integer> lengths = new LinkedHashMap<>();
41	        lengths.put("61", 9); // Australia
42	        lengths.put("1", 10); // North American Numbering Plan
43	        NATIONAL_LENGTHS = lengths;
44	    }
45	
46	    private OwnerTelephone() {
47	    }
48	
49	    /**
50	     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
51	     */
52	    static String toE164(String telephone) {
53	        if (telephone == null) {
54	            return null;
55	        }
56	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
57	        String digits;
58	        if (cleaned.startsWith("+")) {
59	            // Keep the explicit country code; the '+' is re-added below.
60	            digits = cleaned.substring(1);
61	        }
62	        else {
63	            // No country code: assume +61 and drop a single leading '0' from the national digits.
64	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
65	            digits = "61" + national;
66	        }
67	        String e164 = "+" + digits;
68	        if (!E164.matcher(e164).matches()) {
69	            return null;
70	        }
71	        return hasValidNationalLength(digits) ? e164 : null;
72	    }
73	
74	    /**
75	     * Whether the national-number length of {@code digits} (a '+'-less E.164 digit string) matches its
76	     * country code. Unrecognized country codes pass (checked only by the general 8-to-15 rule above).
77	     */
78	    private static boolean hasValidNationalLength(String digits) {
79	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
80	            String code = entry.getKey();
81	            if (digits.startsWith(code)) {
82	                return digits.length() - code.length() == entry.getValue();
83	            }
84	        }
85	        return true;
86	    }
87	}
