326	    /**
327	     * The single Luhn check digit (0-9) computed over the digits contained in the
328	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
329	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
330	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
331	     */
332	    public int getCheckDigit() {
333	        String code = this.customerCode;
334	        if (code == null) {
335	            return 0;
336	        }
337	        int sum = 0;
338	        boolean dbl = true;
339	        for (int i = code.length() - 1; i >= 0; i--) {
340	            char c = code.charAt(i);
341	            if (c < '0' || c > '9') {
342	                continue;
343	            }
344	            int d = c - '0';
345	            if (dbl) {
346	                d *= 2;
347	                if (d > 9) {
348	                    d -= 9;
349	                }
350	            }
351	            sum += d;
352	            dbl = !dbl;
353	        }
354	        return (10 - (sum % 10)) % 10;
355	    }
